export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/**
 * How long a deleted workspace is kept, inert, before the retention sweep
 * removes it. The window is this many 24-hour periods after `archivedAt`.
 */
export const DELETED_WORKSPACE_RETENTION_DAYS: number = 30;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** True when `archivedAt` is at least `DELETED_WORKSPACE_RETENTION_DAYS` × 24h before `now`. */
export function isDeletedWorkspaceRetentionElapsed(
  archivedAt: string,
  now: Date,
): boolean {
  const deletedAt = new Date(archivedAt).getTime();
  if (Number.isNaN(deletedAt)) return false;
  return now.getTime() - deletedAt >= DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
}

