/** Clears `archivedAt` so a workspace inside the retention window is live again. */
export async function restoreOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(restorePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Every workspace that is currently deleted and waiting out its retention window. */
export async function listArchivedOrgs(): Promise<readonly Organization[]> {
  const rows = getDb()
    .select()
    .from(organizations)
    .where(isNotNull(organizations.archivedAt))
    .all();
  return rows.map((row) => toOrganization(row));
}

/**
 * Permanently deletes a workspace whose retention window has closed, and every
 * row that belongs to it. User accounts stay. A session that pointed at the
 * workspace simply no longer has an active workspace. Returns false when the
 * workspace is live or still inside the window, deleting nothing.
 */
export async function purgeExpiredOrganization(
  orgId: OrgId,
  now: Date,
): Promise<boolean> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();

    if (!current?.archivedAt) return false;
    if (!isDeletedWorkspaceRetentionElapsed(current.archivedAt, now)) return false;

    const drop = (orgColumn: typeof comments.orgId, table: Parameters<typeof tx.delete>[0]) => {
      tx.delete(table).where(eq(orgColumn, orgId)).run();
    };

    drop(comments.orgId, comments);
    drop(issueLabels.orgId, issueLabels);
    drop(attachments.orgId, attachments);
    drop(issues.orgId, issues);
    drop(labels.orgId, labels);
    drop(projectMembers.orgId, projectMembers);
    drop(projects.orgId, projects);
    drop(notificationPreferences.orgId, notificationPreferences);
    drop(notifications.orgId, notifications);
    drop(invitations.orgId, invitations);
    drop(members.orgId, members);
    drop(activityEvents.orgId, activityEvents);
    drop(invoices.orgId, invoices);
    drop(subscriptions.orgId, subscriptions);
    drop(webhookDeliveries.orgId, webhookDeliveries);
    drop(webhookEndpoints.orgId, webhookEndpoints);
    drop(searchIndex.orgId, searchIndex);
    drop(rateLimitBuckets.orgId, rateLimitBuckets);
    tx.delete(organizationUsage).where(eq(organizationUsage.orgId, orgId)).run();
    tx.update(sessions)
      .set({ activeOrgId: null, updatedAt: toIsoTimestamp(now) })
      .where(eq(sessions.activeOrgId, orgId))
      .run();
    tx.delete(organizations).where(eq(organizations.id, orgId)).run();
    return true;
  });
}

