 * `Actor` for a deleted workspace — sign-in cannot resolve one — so the caller
 * is named by user id and the `org:restore` check is applied to their membership.
 *
 * A workspace that was never deleted is returned as it stands and publishes
 * nothing. Once the retention window has closed the workspace is gone, whether
 * or not the purge has run.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  if (
    org.archivedAt !== null &&
    isDeletedWorkspaceRetentionElapsed(org.archivedAt, new Date())
  ) {
    throw new NotFoundError("Organization", orgId);
  }

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Organization", orgId);

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
