import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { PermissionDeniedError } from "@/lib/permissions";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runOverdueIssueJob, resetOverdueTracking } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { notify } from "@/server/services/notification-service";
import { acceptInvitation, inviteMember } from "@/server/services/invitation-service";
import {
  deleteOrganization,
  listOrganizationsForUser,
  restoreOrganization,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { resolveActor } from "@/server/services/member-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import * as issueService from "@/server/services/issue-service";
import * as userRepo from "@/server/repositories/user-repository";
import { getDb, organizations, sessions } from "@/server/db";
import { eq } from "drizzle-orm";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("workspace retention", () => {
  it("deletes, blocks, restores, and purges", async () => {
    const tenant = await createTenant("retain");
    await usageRepo.recomputeUsage(tenant.org.id);

    const deletedEvents: string[] = [];
    const off = subscribe("organization.deleted", (p) => {
      deletedEvents.push(p.slug);
    });

    const archived = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(archived.archivedAt).not.toBeNull();
    expect(deletedEvents).toEqual([tenant.org.slug]);
    off();

    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 10,
      cursor: null,
    });
    expect(activity.items).toHaveLength(1);
    expect(activity.items[0]).toMatchObject({
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });

    expect(await listOrganizationsForUser(tenant.userIds.owner)).toEqual([]);
    expect(await resolveActorForOrg(
      { userId: tenant.userIds.owner, email: "x", activeOrgId: tenant.org.id, expiresAt: toIsoTimestamp(new Date(Date.now() + 10000)) },
      tenant.org.slug,
    )).toBeNull();
    expect(await resolveActor(tenant.userIds.owner, tenant.org.id)).toBeNull();

    const created = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "nope",
      body: "nope",
      href: "/",
      actorId: tenant.userIds.owner,
