import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { eq } from "drizzle-orm";
import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { getDb, organizations, sessions, subscriptions, webhookDeliveries } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { acceptInvitation } from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import { resolveActor } from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import {
  deleteOrganization,
  listOrganizationsForUser,
  restoreOrganization,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

function principal(userId: SessionPrincipal["userId"]): SessionPrincipal {
  return {
    userId,
    email: "owner@retain.test",
    activeOrgId: null,
    expiresAt: toIsoTimestamp(new Date(Date.now() + 86_400_000)),
  };
}

describe("workspace retention scratch", () => {
  it("soft-deletes, restores, and purges after the window", async () => {
    const tenant = await createTenant("retain");
    await usageRepo.recomputeUsage(tenant.org.id);

    const deleted: string[] = [];
    const off = subscribe("organization.deleted", (payload) => {
      deleted.push(payload.slug);
    });

    const archived = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    off();
    expect(archived.archivedAt).not.toBeNull();
    expect(deleted).toEqual([tenant.org.slug]);

    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 10,
      cursor: null,
    });
    expect(activity.items).toHaveLength(1);
    expect(activity.items[0]).toMatchObject({
      action: "organization.deleted",
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });

    expect(await listOrganizationsForUser(tenant.userIds.owner)).toEqual([]);
    expect(
      await resolveActorForOrg(principal(tenant.userIds.owner), tenant.org.slug),
    ).toBeNull();
    expect(await resolveActor(tenant.userIds.owner, tenant.org.id)).toBeNull();
    expect(await orgRepo.listTakenOrgSlugs("retain")).toContain(tenant.org.slug);

    expect(
      await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
        title: "nope",
        body: "nope",
        href: "/",
        actorId: tenant.userIds.owner,
      }),
    ).toEqual([]);

    const token = "invite-token-retain";
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "guest@retain.test",
        role: "member",
        expiresInDays: 7,
      },
      tenant.userIds.owner,
      hashToken(token),
    );
    const guest = await userRepo.insertUser({
      email: "guest@retain.test",
      name: "Guest",
      passwordHash: "seed",
    });
    const pendingBefore = await invitationRepo.listPendingInvitations(tenant.org.id);
    await expect(acceptInvitation(guest.id, { token })).rejects.toBeInstanceOf(
      NotFoundError,
    );
    const pendingAfter = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pendingAfter).toHaveLength(pendingBefore.length);

    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      restoreOrganization(guest.id, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const restored: string[] = [];
    const offR = subscribe("organization.restored", (payload) => {
      restored.push(`${payload.slug}:${payload.actorId}`);
    });
    const live = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    offR();
    expect(live.archivedAt).toBeNull();
    expect(restored).toEqual([`${tenant.org.slug}:${tenant.userIds.owner}`]);
    expect(await resolveActor(tenant.userIds.owner, tenant.org.id)).not.toBeNull();

    const unchanged = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(unchanged.archivedAt).toBeNull();
    expect(
      (
        await activityRepo.listActivity({
          orgId: tenant.org.id,
          action: ["organization.restored"],
          limit: 10,
          cursor: null,
        })
      ).items,
    ).toHaveLength(1);

    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    const past = toIsoTimestamp(
      new Date(Date.now() - DELETED_WORKSPACE_RETENTION_DAYS * 24 * 60 * 60 * 1000),
    );
    getDb()
      .update(organizations)
      .set({ archivedAt: past })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await sessionRepo.createSession(
      tenant.userIds.owner,
      "tok-retain",
      toIsoTimestamp(new Date(Date.now() + 86_400_000)),
    );
    getDb()
      .update(sessions)
      .set({ activeOrgId: tenant.org.id })
      .where(eq(sessions.tokenHash, "tok-retain"))
      .run();

    await runCleanupArchivedJob(new Date());
    expect(await orgRepo.findOrgById(tenant.org.id)).toBeNull();
    expect((await sessionRepo.findSessionByTokenHash("tok-retain"))?.activeOrgId).toBeNull();
    expect(await userRepo.findUserById(tenant.userIds.owner)).not.toBeNull();
    expect(await orgRepo.listTakenOrgSlugs("retain")).not.toContain("retain");
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("leaves a freshly deleted workspace out of background jobs", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("inert");
    await usageRepo.recomputeUsage(tenant.org.id);
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "due",
        assigneeId: tenant.userIds.member,
        dueAt: "2020-01-01T00:00:00.000Z",
      }),
    );

    getDb()
      .update(subscriptions)
      .set({
        status: "trialing",
        plan: "growth",
        currentPeriodEnd: "2020-01-01T00:00:00.000Z",
      })
      .where(eq(subscriptions.orgId, tenant.org.id))
      .run();

    const endpoint = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        eventTypes: ["issue.created"],
      },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );

    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const before = await usageRepo.getUsage(tenant.org.id);
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      seen.push(payload.issueId);
    });
    await runOverdueIssueJob(new Date());
    off();
    expect(seen).not.toContain(issue.id);

    await runUsageRollupJob(new Date());
    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.measuredAt).toBe(before.measuredAt);

    const planEvents: string[] = [];
    const offPlan = subscribe("billing.plan_changed", (payload) => {
      planEvents.push(payload.orgId);
    });
    await runTrialExpiryJob(new Date());
    offPlan();
    expect(planEvents).not.toContain(tenant.org.id);
    expect(
      getDb().select().from(subscriptions).where(eq(subscriptions.orgId, tenant.org.id)).get()
        ?.plan,
    ).toBe("growth");

    await runWebhookDeliveryJob(new Date());
    const row = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.id, delivery.id))
      .get();
    expect(row?.status).toBe("failed");

    await runCleanupArchivedJob(new Date());
    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();
    expect(await orgRepo.findOrgById(tenant.org.id)).toMatchObject({
      archivedAt: expect.any(String),
    });
  });
});

